INSERT INTO `ha_term_relationships` (`object_id`,`term_taxonomy_id`,`term_order`) SELECT @translation_id,tt.term_taxonomy_id,0 FROM `ha_term_taxonomy` tt JOIN `ha_terms` t ON t.term_id=tt.term_id WHERE @translation_id IS NOT NULL AND tt.taxonomy='category' AND t.slug='en' AND NOT EXISTS (SELECT 1 FROM `ha_term_relationships` r WHERE r.object_id=@translation_id AND r.term_taxonomy_id=tt.term_taxonomy_id) LIMIT 1;
INSERT INTO `ha_posts` (`post_author`,`post_date`,`post_date_gmt`,`post_content`,`post_title`,`post_excerpt`,`post_status`,`comment_status`,`ping_status`,`post_name`,`post_modified`,`post_modified_gmt`,`post_parent`,`guid`,`menu_order`,`post_type`,`post_mime_type`,`comment_count`) SELECT 1,NOW(),UTC_TIMESTAMP(),'<p>Карбонгори кали (طالب) яке аз самараноктарин соҳаҳои кишоварчии Эрон ва Шамоле ба шумор меравад, аммо ин маҳсулот ба тағйирёти зоналӣ, зараррасон ва бемориҳои гуногун эҳсоскор аст. Бисёре аз деҳқонҳо тасаввур мекунанд, ки барои кам кардани осеб танҳо бояд ба доруҳои кимиёвӣ такя кунанд. Аммо ҳaqiqат ин аст, ки <strong>идоракунии дурусти намнокӣ ва ғизои растани тавассути обӣ доиқатрӣ</strong> метавонад таъсири мустақимро дар дараҷаи эҳсоскориҳои растани ба зараррасонҳо ва бемориҳои кали тавассути обӣ доиқатрӣ гузорад. Вақте ки растани Stress-и камтарро таҳаммул мекунад, муқовимати табилии он зидди ҳуҷуми патугенҳо бо тарзи шағфзуд меафзояд. Дар ин дастورномасо, шуморо бо асосҳои илмӣ ва амалӣ дар бораи идоракунии муваззифаи обӣ ва мубориза бо зараррасонҳо барои ҳосилнокии максималӣ ва сифати маҳсулот ошно менамоем.</p><h2>Таъсири мустақими обӣ доиқатрӣ ба экологияи зараррасонҳо ва бемориҳои кали тавассути обӣ доиқатрӣ</h2><p>Дар хилофи обӣ кардани шитобона (гирчавобӣ), ки боиси эҷоди намнокии баланд дар сатҳ ва муҳити мулоим барои афзоиши зангҳо ва пӯстпӯраҳо мегардад, системаҳои фавқуддабортанҳо, монанди <a href="https://navar-abyari.ir/%D9%85%D8%B1%D8%A7%D8%AD%D9%84-%D9%86%D8%B5%D8%A8-%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE/">рибони тейпӣ</a> ва доиқатрӣ, танҳо роҳи растани ва решаҳоро тар мекунанд. Ин боиси коҳиши шадиди намнокӣ дар фазои байни қаторҳо ва сатҳи кӯлак ва баргҳо мегардад. Коҳиши намнокии нисбии ҳаво дар атрофи растани, монеи эҷоди доири зангӣ ва коҳиши шадиди беморӣ ба шинакҳои шағал, зардолӣ барги ва сафедкуни пудрӣ мегардад.</p><h3>Инъикоси намнокӣ ба паҳншавии вирусҳои кали</h3><p>Бемориҳои вирусӣ, ба монанди мозаики кали (WMMV), одатан тавассути пашаки сабз ва ҳашараҳои дигари ҷолиб интиқол меёбанд. Яке аз омилҳои асосии ҷалби ин ҳашарҳо, шаъфулӯлупуршавии аз ҳад зиёди ҳавокии растани аз сабаби обӣ ва ғизокунии нодуруст аст. Бо иҷрои дақиқи барномаи обӣ доиқатрӣ, шумо метавонед Stress-и таҳаммулшавии обро ба минимум расонед. Вақте ки растани ба Stress-и шадиди хушкӣ парҳез кунад, системаи иммунии он таъсири бешаро нишон медиҳад ва ҳашараҳои ғайриилоҷирро камтар ҷалб мекунад. Шумо метавонед барои ошноӣ бо асосҳои насби дурусти лӯлаҳо барои зиёд кардани давраҳои ғизоӣ, ба саҳифаи <a href="https://navar-abyari.ir/nuqtahoi-muhim-pesh-az-nasbi-leantai-tip-dar-maydon/">Нуқтаҳои муҳим пеш аз насби лӯлаи тейпӣ дар майдони деҳқонӣ</a> муроҷиат кунед. Ин нуқтаҳои техникӣ барои интегралятсияи система ва пешгирии Stress-ҳои аввалин, ки боиси эҳсоскориҳои растани ба зараррасонҳо мегарданд, ҳаётянд.</p><h2>Бемориҳои решаҳо: хатарактарин таҳдид дар системаи обӣ доиқатрӣ</h2><p>Бемориҳои решаҳо, аз ҷумла пӯлсики фарасия ва пикария, аз муҳимтарин зараррасонҳо ва бемориҳои кали тавассути обӣ доиқатрӣ мебошанд. Ин бемориҳо аз сабаби намнокии баланд дар ҳудуди решаҳо пайдо мешаванд. Агар системаи обии шумо дуруст танзим нашуда бошад ва дозаларо ба фосилаҳои хеле наздик ҷорӣ кунед, хок ба хунукӣ гирифтор мешавад ва ин тавр патугенҳои зангӣ дар ҷамъовариҳои решаҳо афзоиш меёбанд. Дар натиҷа, растани наметавонад моддаҳои ғизоиро ҷабб кунад ва зуд заҳал мешавад. Роҳи амалӣ, назорати дақиқи таймингири ва фосила байни зонаҳои обӣ аст, то хок то обҳои ҳаво дошта бошад. Инчунин, истифодаи тафсилотҳои зараррасонҳои аминбросазурсва барои ба кор андӯхтани филтратсияи дурусти системаҳо барои пешгирии бастани назлҳои обӣ доиқатрӣ, ва дар натиҷа эҷоди минтақаҳои хушк, ки дар он ҷо патугенҳо зинда монанданд, хеле муҳим аст.</p><h2>Пешгирии ҳуҷуми пашаки сабз ва шафе аз рӯи танзими дақиқи намнокӣ</h2><p>Ҳашараҳои зараррасон, биҳисобгирифтни пашаки сабз, одатан дар шароите фаъолтар мебошанд, ки растани заиф ва камоб бошад. Бинобар ин, обии мунтазам ва кофӣ тавассути доиқатрӣ нақши ҳаётӣ дар пешгирии ҳуҷуми пашаки сабз ва шафе мегирад. Ин ҳашарҳо одатан дар назди растаниҳое мегиранд, ки нишондиҳандаи Stress-и пеш аз муддат мебошанд. Бо ҳифзи нақшаи намнокӣ, растании кали солимтар буда ва ҳашараҳои ғайриилоҷирро ҷалб намекунад. Шумо метавонед барои ошноӣ бо роҳҳои идоракунии системаҳои лӯлаҳо, ба дастурномасо <a href="https://navar-abyari.ir/tol-fotuti-nori-tip-dar-kunor-dukhtashuda-va-ba-plastka/">толи фукти нои тейп дар паҳлӯи духташуда ва бо пластик</a> муроҷиат кунед, то боварии пурра ба тавофулҳои солимаи худ барои обии якхела дошта бошед.</p><h2>Ғизокунии баҳодиҳиш ва назорати зараррасонҳо дар системаи доиқатрӣ</h2><p>Яке аз бурҷҳои нозираҳо ва хоси системаҳои борик (дарпӣ) ва <a href="https://navar-abyari.ir/%D9%86%D9%88%D8%A7%D8%B1-%D8%AA%DB%8C%D9%BE-%D9%BE%D8%A7%D9%BE%D8%B1%DB%8C%DA%A9%D8%A7/">шарифҳои қатъии паприка</a>имконият дорад, ки таъмини озуаи дақиқ (фритизация) анҷом шавад. Дар ин усул маводи озупаргор ва ҳатто ҳалкунандаҳои биопром (масалан, триходерма) бевосита ба минтакаи решаҳо инъикос карда мешаванд. Истифодаи триходерма дар ин система яке аз роҳҳои самаранок барои дур шудан аз пӯришҳои реша ва истифодаи решаҳои зинда бар муқобилат бо патогенҳои дар хок мавҷуда мебошад. Ин усул ниёз ба доруи кимиёвиро ба таври назаррас коҳиш медиҳад. Ҳамзамон, истифодаи ҳалкунандаҳои зидди асбобҳои хозиракунанда тавассути система пеш аз оғози мавсими кишт метавонад шумораи бориҳои бактерияҳои хозиракунанда дар хокро коҳиш диҳад.</p><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-طالبی-با-آبیاری-قطرهای-تصویر-شاخص.webp" alt="آفات و بیماری‌های طالبی با آبیاری قطره‌ای - تصویر 1"/><figcaption>crop pests diseases drip irrigation طالبی</figcaption></figure></p><h2>Афатҳо ва бемориҳои тӯбиқ бо борик (дарпӣ): Нуқтаҳои асосии амалӣ</h2><p>Барои он ки аз бурҷҳои борик дар назорати афатҳо истифода баред, бояд нуқтаҳои зеринро риоя кунед. Ин нуқтаҳо омехтаи таҷриба ва дониши илмӣ мебошанд, ки бояд дар деҳқонии шумо татбиқ шаванд:</p><ol><li><strong>Поксозӣ ва хозиракунии система:</strong> Пеш аз оғози ҳар мавсими кишт, системаро аз ҷиҳати вуҷуди қарч ва бактерияҳо пӯк қилед ва хозир кунед. Агар система иллатнок бошад, борик на ба кӯмак ба растанӣ, балки омили паҳн шудани беморӣ хоҳад буд.</li><li><strong>Борик мувофиқ ба ниёзи растанӣ:</strong> Аз борик дар даврҳои муайян рӯзона парҳез кунед. Беҳтар аст, ки дар асоси шароити ҳаво ва синни растанӣ ҳаҷми борикро тағир диҳед. Растание, ки дар фазаи афзоишӣ қарор доранд, ба об бештар ниёз доранд ва ин метавонад ҳиссиёт пӯришро баланд барад.</li><li><strong>Истифодаи бозеҳандаҳои пахшшандаи нисбат:</strong> Ин бозеҳандаҳо сабаб мешаванд, ки об дар сатҳи хок васеътар паҳн шавад ва аз ҷамъ шудани намӣ дар як ҷо пешгирӣ кунад, ки ин омили суръати афзоиши қарч аст.</li><li><strong>Назорати доимии хок ва баргҳо:</strong> Ба таври мунтазам зумурди хок ва баргҳои тӯбиқро барои мушоҳидаи аломатҳои зудаҳои афат санҷед. Борик боиси пинҳонии баъзе аломатҳо мегардад, бинобар ин мушоҳидаи диққатнокӣ лозим аст.</li><li><strong>Таъмини озуаи дақиқ бо маводи биопром:</strong> Имконияти системаро истифода баред, то ки триходерма ва бацилус дар минтакаи решаҳо инъикос карда шаванд. Ин маводҳо душмани қарчҳои пӯришкунанда мебошанд ва аз афатҳо ва бемориҳои тӯбиқ бо борик ба таври табиӣ пешгирӣ мекунанд.</li></ol><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-طالبی-با-آبیاری-قطرهای-کاربرد-عملی.webp" alt="آفات و بیماری‌های طالبی با آبیاری قطره‌ای - تصویر 2"/><figcaption>crop pests diseases drip irrigation طالبی</figcaption></figure></p><h2>Ҷадвали барномаи ҳафтакунандаи назорати намӣ ва пешгирӣ аз афат</h2><p>Барои дорои будани боғи саломати хурмачи, беҳтар аст, ки нақшаи шаффоф дошта бошед. Ҷадвали зерин роҳнамои амалӣ барои идоракунии намӣ ва назорати зарар расонандагон дар системаҳои қатрагарӣ мебошад:</p><table><tr><th>Синни растани</th><th>Ёриҳои обпоиш бо қатра</th><th>Нуктаҳои назорати зарар расонандагон</th></tr><tr><td>Аз нармолӣ то пеш аз гулбурдон</td><td>Обпоиши вазнин ва такроршуда, таваҷҷуҳ ба намии решаҳо</td><td>Назорати ҳашароти хурд, идоракунии сабзпашак дар муҳити парвариш</td></tr><tr><td>Гулбурдон ва мевобарорӣ</td><td>Кам кардани миқдори об, зиёд шудани фосилаи вақт</td><td>Бозистодан аз обпоии баргҳо, назорати қаракунии гул</td></tr><tr><td>Афзоиш ва мевобарорӣ</td><td>Обпоиш мувофиқи зарурати намӣ, назорати стресс</td><td>Ошноии зуд вақтӣ ба аломатҳо, идоракунии қарақӣ ва бактериявӣ</td></tr></table><p>Истифодаи <a href="https://navar-abyari.ir/%D9%85%D9%82%D8%AF%D8%A7%D8%B1-%D8%A8%D8%B0%D8%B1-%D8%B4%D8%A8%D8%AF%D8%B1-%D8%AF%D8%B1-%D9%87%DA%A9%D8%AA%D8%A7%D8%B1/">Миқдори боди дар гектар</a> Ба таври дуруст, дар канори обпоиш, боиси мешавад, ки зичии растаниҳо дар сатҳи боғ мувофиқ бошад. Зичии зиёд боиси кам шудани ҷараёни ҳаво ва зиёд шудани намии нисбӣ дар боғ мешавад ва дар натиҷа зарар расонандагон ва бемориро маъмултар мекунад.</p><h2>Бемориҳои хурмачи: аломатҳои эҳтимолӣ ва усулҳои ташхис бо обпоии қатрагарӣ</h2><p>Ошноии зуд вақтӣ ба аломатҳо, калиди идоракунии зарар расонандагон ва бемориҳои хурмачи бо обпоии қатрагарӣ аст. Агар ларгҳои буррасо ё зардӣ дар баргҳо, қарақии нарми решаҳоро дар наздикии қатрагарҳо ба назар расонида бошед, эҳтимолан ба мушкили гидролуксис расидаед. Ин мушкилӣ, ки ба сабаби таҳмини фишор ва вайроншавии система ба вуҷуд меояд, боиси мешавад, ки намӣ дар як ҷамъидашуда гиряш кунад ва қарақӣ вазб шавад. Барои пешгирии ин ҳодиса, аз қатрагарҳои худпاکшуда истифода баред, ки аз ҷамъшавии моддаҳо ва ба вуҷуд омадани ноҳияҳои беморкор пешгирӣ мекунанд. Аломатҳои дигар низ кам шудани афзоиши решаҳо, тағйири ранги дигарон ва парокандашавии зуд вақтии мева мебошад. Дар ҳамаи ин ҳолатҳо, аввал бояд аз кори дурусти системаҳои обпоиш ва қатрагарҳо ҳароҳис баред, сипас ба зерҳои кимиёвӣ ё биоперм муроҷиат кунед.</p><h2>Саволҳои пурсидашаванда дар идоракунии зарароварон ва бемориҳои хирмашт бо оварии қадроқӣ</h2><h3>Оё оварии қадроқӣ метавонад вайронсозии вирусии мозаикавиро пешгирӣ кунад?</h3><p>Оварии қадроқӣ вирусии мозаикавиро бевосита нест намекунاد, аммо бо нигоҳ доштани солимӣ ва устувории растани, дараҷаи ҳамлаи кӯрпашаи сафед (ки воситаи паҳкунандаи вирус аст)-ро ба таври маънодор коҳиш медиҳад. Растаниҳое, ки бо оварии қадроқӣ солим мемонанд, камтарини зарароварони парвозкунанда мақсад қарор мегиранд.</p><h3>Оё фосилаҳои қаторкунакиҳо дар назорати кӯрпагии реша аҳамият дорад?</h3><p>Бале, хеле муҳим аст. Фарогирии беҳтарин метавонад ҷамъшавии намдорӣ дар баъзе минтақаҳои муайянро пешгирӣ кунад. Барои оварии системавӣ, тавсия мекардашад, ки фосилаҳои байни қаторкунакиҳо вобаста ба синни растани танзим карда шаванд. Вақте ки растани мекашад, фосилаҳо бояд зиёдтар шаванд, то решаҳо ба таври баробар оварӣ шаванд.</p><h3>Оё ман метавонам моддаҳои кимиёвии зарароноро тавассути қаторкунакиҳо пур кардам?</h3><p>Баъзе моддаҳои кимиёвии зарароноро, хусусан гуррараксунандаҳои решагӣ, метавон тавассути системаи фёртитизатсия партоуд. Аммо пеш аз истифода, ҳатман мутобиқатали моддаи зараронокро бо қаторкунакиҳои пластикӣ ва металлӣ санҷед, зеро баъзе моддаҳои кимиёвӣ деформатсия ё ханҷориши системаро ба вуҷуд меоранд. Ҳамеша ба дастурамбарҳои техникии ҳар як моддаи зараронок диққат диҳед.</p><h3>Оё коҳиши сарфи об бо оварии қадроқӣ камомиши даромади зарароваронро дар умум таъмин мекунад?</h3><p>Не, коҳиши сарфи об бевосита ба назорати зарароварон оварда намерасад, балки ин раводид тавассути тағйироти экоистеъмоли соҳиш баръакс аст. Оварии қадроқӣ намдории фазои байни раҳҳоро коҳиш медиҳад ва ин боиси камомишудани аҳолии зарароварони моҳубард мебошад. Бинобар ин, ин як раванди беvosita аммо самаранок аст.</p><p><figure class="wp-block-image size-large"><img src="https://navar-abyari.ir/wp-content/uploads/2026/09/navar-article-generated/آفات-و-بیماریهای-طالبی-با-آبیاری-قطرهای-جزئیات-فنی.webp" alt="آفات و بیماری‌های طالبی با آبیاری قطره‌ای - تصویر 3"/><figcaption>zararavaron bimarixon ovari qadrobakhsh khirmash</figcaption></figure></p><h2>Хулоса: Ҳалҳои ягонашуда барои маҳсулоти солим</h2><p>Идоракунии зарароварон ва бемориҳои хирмашт бо оварии қадроқӣ, асосгузории навоваронаест, ки дар равонаи пешгирӣ ва назорати дақиқтари муҳити рушди растани мубориза мекунад. Бо истифода аз қоидаҳои насбу нигоҳубини дурусти қаторкунакиҳо, ба кор гирифтани фёртитизатсияи мувофиқ ва назорати мунтазам, метавон муҳите ташкил дод, ки дар он растаниҳо солимтар мекашанд ва ба ҳамлаи патогенҳо устувортаранд. Ин усул на танҳо ба коҳиши истифодаи моддаҳои кимиёвии зараронок оварда мерасонад, балки тавассути зиёд кардани устувории табиии растани, ба ҳифзи солимӣ ва сифати маҳсулот мерасонад. Агар шумо роҳҳои зиёдтар барои зиёд кардани самаранокии истеҳсолот ва назорати зарароваронро ҷустуҷӯ кунед, тавсия мекунем, ки бо хондани мақола <a href="https://navar-abyari.ir/oval-watermelon-yield-per-hectare-iraq/">Самаранокии хирмашт ва куматоқ дар ҳама гектар</a> Дар соҳаҳои дигари оварии қадроқӣ шинос шавед. Бо ҳамҷустии дониш дар оварӣ ва мубориза бо зарароварон, соҳиши самарабахш ва солим хоҳед дошт, ки ҳам аз ҷиҳати иқтисодӣ ва ҳам аз ҷиҳати экологӣ муфид аст. Каморӣ дар ин роҳ ба назорати доимӣ ва омодасозии идомадорӣ ниёз дорад, то ботун бавидан ба мушкилот ва зарароварони нав пешина карда шаванд.</p>','Кориши калонкунии ҳашарот ва бемориҳои қурус (түлбӣ) дар системҳои обёрӣ тасодуфан ва наварҳои тиоо','Ориёб кардан бо тамчилка ҷиноби ягона роҳи кам кардани истеъмоли об нест, балки либоси потентсоф барои идоракунии зараррасонҳо ва бемориҳои динуяш меро. Дар ин мақола мо усулҳои пешгирӣ ва идоракунӣ-ро баррасӣ мекунем.','publish','closed','closed','kalis-kolonkunii-hasorot-va-bemoriha-yi-tulbi-dar-sistemihoi-obori-tasadufan-va-navarhoyi-',NOW(),UTC_TIMESTAMP(),0,'',0,'post','',0 WHERE @source_post_id IS NOT NULL AND @translation_id IS NULL AND @slug_conflict IS NULL;
